// Refreshes the auto-generated block of docs/FACTS.md from the code and git history.
// Usage: npm run facts            (rewrite the block)
//        npm run facts -- --check (exit 1 if the block is out of date; nothing is written)
import { execFileSync } from 'node:child_process';
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { HEROES } from '../src/sim/heroes';
import { SKILLS } from '../src/sim/skills';
import { RELICS } from '../src/sim/relics';
import { LINES } from '../src/sim/types';
import { SIM_VERSION } from '../src/sim/combat';
import { RUN_VERSION, WIN_TARGET, START_HP, HERO_CHOICES, MAX_SLOTS, SHOP_SIZE } from '../src/sim/run';
import { HEROES_EN } from '../src/client/i18n_en';

const ROOT = join(import.meta.dirname, '..');
const FILE = join(ROOT, 'docs', 'FACTS.md');
const START = '<!-- facts:auto:start -->';
const END = '<!-- facts:auto:end -->';

const git = (...args: string[]) => execFileSync('git', args, { cwd: ROOT, encoding: 'utf8' }).trim();
const today = new Date().toISOString().slice(0, 10);
const weekAgo = new Date(Date.now() - 7 * 864e5).toISOString().slice(0, 10);
const commitsTotal = Number(git('rev-list', '--count', 'HEAD'));
const commitsWeek = Number(git('rev-list', '--count', `--since=${weekAgo}`, 'HEAD'));
const firstCommit = git('log', '--reverse', '--format=%ad', '--date=short').split('\n')[0];
const head = git('log', '-1', '--format=%h %ad', '--date=short');
const securityChecks = (readFileSync(join(ROOT, 'scripts', 'security-check.ts'), 'utf8').match(/\bcheck\(/g) ?? []).length - 1; // minus the definition

const skills = Object.values(SKILLS);
const uniques = skills.filter((s) => s.hero).length;
const heroes = HEROES.map((h) => `${HEROES_EN[h.id]?.name ?? h.id} (${h.name}, ${h.line})`).join(', ');

const block = `${START}
_Generated by \`npm run facts\` on ${today} from commit ${head}. Do not edit by hand; edit the code and re-run._

| Fact | Value |
|---|---|
| Heroes | **${HEROES.length}**: ${heroes} |
| Skills | **${skills.length}** (${uniques} hero uniques + ${skills.length - uniques} shared), each Lv1 → Lv2 → Lv3 with 2 Lv2 paths |
| Skill lines | **${LINES.length}**: ${LINES.join(', ')} |
| Relics | **${RELICS.length}** |
| A run | pick 1 of ${HERO_CHOICES} heroes · ${START_HP} HP · win **${WIN_TARGET}** fights to clear · shop of ${SHOP_SIZE} · up to ${MAX_SLOTS} skill slots |
| Engine versions | sim v${SIM_VERSION} · run v${RUN_VERSION} (deterministic: same builds + seed = same fight) |
| Server abuse tests | ${securityChecks} checks in \`scripts/security-check.ts\` |
| Commits | ${commitsTotal} total since ${firstCommit} · ${commitsWeek} in the last 7 days |
${END}`;

const text = readFileSync(FILE, 'utf8');
const i = text.indexOf(START), j = text.indexOf(END);
if (i < 0 || j < 0) throw new Error(`docs/FACTS.md needs the ${START} … ${END} markers`);
// the date and commit line change every run, so compare without it
const strip = (s: string) => s.replace(/^_Generated by.*$/m, '');
const old = text.slice(i, j + END.length);
if (process.argv.includes('--check')) {
  const stale = strip(old) !== strip(block);
  console.log(stale ? 'docs/FACTS.md is out of date: run npm run facts' : 'docs/FACTS.md is up to date');
  process.exit(stale ? 1 : 0);
}
writeFileSync(FILE, text.slice(0, i) + block + text.slice(j + END.length));
console.log(`docs/FACTS.md updated: ${HEROES.length} heroes, ${skills.length} skills, ${RELICS.length} relics, ${commitsTotal} commits`);
